-- Captures objects/config that were created via ad-hoc SQL so the repo's migration history fully
-- reproduces the engine: admin_set_learning_source + the engine_config snapshot + APIFY secret name.
create or replace function public.admin_set_learning_source(p_id uuid, p_handle text default null, p_profile_url text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare row public.learning_sources%rowtype; h text;
begin
  if not public.is_admin_caller() then raise exception 'not authorized'; end if;
  h := nullif(regexp_replace(coalesce(p_handle,''), '^@|\s', '', 'g'), '');
  update public.learning_sources set
    handle = coalesce(h, handle),
    profile_url = coalesce(nullif(p_profile_url,''), case when h is not null then 'https://instagram.com/'||h else profile_url end)
  where id = p_id returning * into row;
  if row.id is null then raise exception 'source not found'; end if;
  return to_jsonb(row);
end; $$;
revoke all on function public.admin_set_learning_source(uuid, text, text) from public, anon;
grant execute on function public.admin_set_learning_source(uuid, text, text) to authenticated;

insert into public.app_secret_names (name, label, is_public) values ('APIFY_TOKEN', 'Apify (IG scraper ingest)', false) on conflict (name) do nothing;

